23	impl StatisticsColumns {
24	    fn new_null(dtype: &DataType, height: usize) -> Self {
25	        Self {
26	            min: Column::full_null(PlSmallStr::EMPTY, height, dtype),
27	            max: Column::full_null(PlSmallStr::EMPTY, height, dtype),
28	            null_count: Column::full_null(PlSmallStr::EMPTY, height, &IDX_DTYPE),
29	        }
30	    }
31	
32	    fn from_arrow_statistics(
33	        statistics: ArrowColumnStatisticsArrays,
34	        field: &ArrowField,
35	    ) -> PolarsResult<Self> {
36	        Ok(Self {
37	            min: unsafe {
38	                Series::_try_from_arrow_unchecked_with_md(
39	                    PlSmallStr::EMPTY,
40	                    vec![statistics.min_value],
41	                    field.dtype(),
42	                    field.metadata.as_deref(),
43	                )
44	            }?
45	            .into_column(),
46	
47	            max: unsafe {
48	                Series::_try_from_arrow_unchecked_with_md(
49	                    PlSmallStr::EMPTY,
50	                    vec![statistics.max_value],
51	                    field.dtype(),
52	                    field.metadata.as_deref(),
53	                )
54	            }?
55	            .into_column(),
56	
57	            null_count: Series::from_arrow(PlSmallStr::EMPTY, statistics.null_count.boxed())?
58	                .into_column(),
59	        })
60	    }
61	
62	    fn with_base_column_name(self, base_column_name: &str) -> Self {
63	        let b = base_column_name;
64	
65	        let min = self.min.with_name(format_pl_smallstr!("{b}_min"));
66	        let max = self.max.with_name(format_pl_smallstr!("{b}_max"));
67	        let null_count = self.null_count.with_name(format_pl_smallstr!("{b}_nc"));
68	
69	        Self {
70	            min,
71	            max,
72	            null_count,
73	        }
74	    }
75	}
