77	pub(super) async fn calculate_row_group_pred_pushdown_skip_mask(
78	    row_group_slice: Range<usize>,
79	    use_statistics: bool,
80	    predicate: Option<&ScanIOPredicate>,
81	    metadata: &Arc<FileMetadata>,
82	    projected_arrow_fields: Arc<[ArrowFieldProjection]>,
83	    // This is mut so that the offset is updated to the position of the first
84	    // row group.
85	    mut row_index: Option<RowIndex>,
86	    verbose: bool,
87	) -> PolarsResult<Option<Bitmap>> {
88	    if !use_statistics {
89	        return Ok(None);
90	    }
91	
92	    let Some(predicate) = predicate else {
93	        return Ok(None);
94	    };
95	
96	    let Some(sbp) = predicate.skip_batch_predicate.as_ref() else {
97	        return Ok(None);
98	    };
99	
100	    let sbp = sbp.clone();
101	
102	    let num_row_groups = row_group_slice.len();
103	    let metadata = metadata.clone();
104	    let live_columns = predicate.live_columns.clone();
105	
106	    // Note: We are spawning here onto the computational async runtime because the caller is being run
107	    // on a tokio async thread.
108	    let skip_row_group_mask = async_executor::spawn(TaskPriority::High, async move {
109	        let row_groups_slice = &metadata.row_groups[row_group_slice.clone()];
110	
111	        if let Some(ri) = &mut row_index {
112	            for md in metadata.row_groups[0..row_group_slice.start].iter() {
113	                ri.offset = ri
114	                    .offset
115	                    .saturating_add(IdxSize::try_from(md.num_rows()).unwrap_or(IdxSize::MAX));
116	            }
117	        }
118	
119	        let mut columns = Vec::with_capacity(1 + live_columns.len() * 3);
120	
121	        let lengths: Vec<IdxSize> = row_groups_slice
122	            .iter()
123	            .map(|rg| rg.num_rows() as IdxSize)
124	            .collect();
125	
126	        columns.push(Column::new("len".into(), lengths));
127	
128	        for projection in projected_arrow_fields.iter() {
129	            let c = projection.output_name();
130	
131	            if !live_columns.contains(c) {
132	                continue;
133	            }
134	
135	            let mut statistics = load_parquet_column_statistics(row_groups_slice, projection)?;
136	
137	            // Note: Order is important here. We re-use the transform for the output column, meaning
138	            // that it may set the column name.
139	            statistics.min = projection.apply_transform(statistics.min)?;
140	            statistics.max = projection.apply_transform(statistics.max)?;
141	
142	            let statistics = statistics.with_base_column_name(c);
143	
144	            columns.extend([statistics.min, statistics.max, statistics.null_count]);
145	        }
146	
147	        if let Some(row_index) = row_index {
148	            let statistics = build_row_index_statistics(&row_index, row_groups_slice)
149	                .with_base_column_name(&row_index.name);
150	
151	            columns.extend([statistics.min, statistics.max, statistics.null_count]);
152	        }
153	
154	        let statistics_df = DataFrame::new(num_row_groups, columns)?;
155	
156	        sbp.evaluate_with_stat_df(&statistics_df)
157	    })
158	    .await?;
159	
160	    if verbose {
161	        eprintln!(
162	            "[ParquetFileReader]: Predicate pushdown: \
163	            reading {} / {} row groups",
164	            skip_row_group_mask.unset_bits(),
165	            num_row_groups,
166	        );
167	    }
168	
169	    Ok(Some(skip_row_group_mask))
170	}
