172	fn load_parquet_column_statistics(
173	    row_groups: &[RowGroupMetadata],
174	    projection: &ArrowFieldProjection,
175	) -> PolarsResult<StatisticsColumns> {
176	    let arrow_field = projection.arrow_field();
177	
178	    let null_statistics = || {
179	        Ok(StatisticsColumns::new_null(
180	            &DataType::from_arrow_field(arrow_field),
181	            row_groups.len(),
182	        ))
183	    };
184	
185	    // This can be None in the allow_missing_columns case.
186	    let Some(idxs) = row_groups[0].columns_idxs_under_root_iter(&arrow_field.name) else {
187	        return null_statistics();
188	    };
189	
190	    // 0 is possible for possible for empty structs.
191	    //
192	    // 2+ is for structs. We don't support reading nested statistics for now. It does not
193	    // really make any sense at the moment with how we structure statistics.
194	    if idxs.is_empty() || idxs.len() > 1 {
195	        return null_statistics();
196	    }
197	
198	    let idx = idxs[0];
199	
200	    let Some(statistics) = deserialize_all(arrow_field, row_groups, idx)? else {
201	        return null_statistics();
202	    };
203	
204	    StatisticsColumns::from_arrow_statistics(statistics, arrow_field)
205	}
